const REQUIRED_COMPARE_FIELDS = Object.freeze(['fullName','gender','birthDate','birthPlace','hometown','birthRegistrationPlace','currentAddress','permanentAddress','citizenId','phone','fatherName','fatherPhone','motherName','motherPhone']);
