  const [selectedId,setSelectedId]=useState(()=>activeStudents[0]?.id||'');
  const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');const [section,setSection]=useState('paper');
  const [scanOpen,setScanOpen]=useState(false);const [scanTarget,setScanTarget]=useState('auto');const [scanFile,setScanFile]=useState(null);const [scanResult,setScanResult]=useState(null);const [scanFields,setScanFields]=useState({});const [scanBusy,setScanBusy]=useState(false);const [scanProgress,setScanProgress]=useState(0);const [scanMessage,setScanMessage]=useState('');const [preview,setPreview]=useState(null);const [syncBusy,setSyncBusy]=useState(false);const [editingSource,setEditingSource]=useState('');const [sourceDraft,setSourceDraft]=useState({});const [sourceSaving,setSourceSaving]=useState(false);const [excelBusy,setExcelBusy]=useState(false);const [excelImporting,setExcelImporting]=useState(false);const [excelError,setExcelError]=useState('');const [excelPreview,setExcelPreview]=useState(null);const [excelAssignments,setExcelAssignments]=useState({});const [moetExcelBusy,setMoetExcelBusy]=useState(false);const [moetExcelImporting,setMoetExcelImporting]=useState(false);const [moetExcelError,setMoetExcelError]=useState('');const [moetExcelPreview,setMoetExcelPreview]=useState(null);const [moetExcelAssignments,setMoetExcelAssignments]=useState({});const fileRef=useRef(null);const excelFileRef=useRef(null);const moetExcelFileRef=useRef(null);
  useEffect(()=>{if(!activeStudents.some((student)=>String(student.id)===String(selectedId)))setSelectedId(activeStudents[0]?.id||'');},[activeStudents,selectedId]);
  useEffect(()=>{setEditingSource('');setSourceDraft({});},[selectedId,section]);
  const selectedStudent=activeStudents.find((student)=>String(student.id)===String(selectedId))||null;
  const selectedRecord=selectedStudent?ensureRecord(records[selectedStudent.id],selectedStudent):null;
  const selectedIssues=selectedRecord?issueList(selectedRecord):[];
  useEffect(()=>{
    if(!selectedStudent||!selectedRecord||!studentRecordCloudEnabled())return;
    const keepPaths=['paper','vnedu','moet'].flatMap((sourceKey)=>(selectedRecord.sources?.[sourceKey]?.captures||[]).map((capture)=>capture.cloudPath).filter(Boolean));
    cleanupStudentRecordCloudOrphans({workspaceId:workspace.id,studentId:selectedStudent.id,keepPaths}).catch(()=>{});
  },[workspace.id,selectedStudent?.id,selectedRecord?.sources?.paper?.captures?.length,selectedRecord?.sources?.vnedu?.captures?.length,selectedRecord?.sources?.moet?.captures?.length]);
  const grade=String(workspace.classProfile?.grade||'').trim();
  const summaries=useMemo(()=>{let complete=0,needs=0,mismatches=0;activeStudents.forEach((student)=>{const record=ensureRecord(records[student.id],student);const progress=recordProgress(record,grade);const issues=issueList(record);if(progress>=95&&!issues.length)complete+=1;else needs+=1;if(issues.length)mismatches+=1;});return{total:activeStudents.length,complete,needs,mismatches};},[activeStudents,grade,records]);
  const visibleStudents=useMemo(()=>activeStudents.filter((student)=>{const record=ensureRecord(records[student.id],student);const progress=recordProgress(record,grade);const issues=issueList(record);if(filter==='complete'&&!(progress>=95&&!issues.length))return false;if(filter==='missing'&&progress>=95)return false;if(filter==='issues'&&!issues.length)return false;const needle=normalized(query);return!needle||normalized([student.fullName,student.code,student.parentName,student.parentPhone].join(' ')).includes(needle);}),[activeStudents,filter,grade,query,records]);
  const commitRecord=async(studentId,nextRecord,message)=>onCommit({...workspace,studentRecords:{...records,[studentId]:nextRecord}},message);
  const patchRecord=async(patch,message='Đã cập nhật hồ sơ học sinh.')=>{if(!selectedStudent||!selectedRecord)return;const next={...selectedRecord,...patch,audit:[...(selectedRecord.audit||[]),{id:uid('audit'),at:nowIso(),by:currentUser?.name||currentUser?.email||'GVCN',action:message}].slice(-80)};await commitRecord(selectedStudent.id,next,message);};
  const setDocStatus=async(key,status)=>patchRecord({checklist:{...selectedRecord.checklist,[key]:status}},'Đã cập nhật checklist hồ sơ.');
  const openScanner=(target='auto')=>{if(!selectedStudent)return;setScanTarget(target);setScanFile(null);setScanResult(null);setScanFields({});setScanProgress(0);setScanMessage('');setScanOpen(true);};
  const recognize=async(file)=>{if(!file)return;setScanFile(file);setScanBusy(true);setScanProgress(0);setScanMessage('Đang chuẩn bị OCR…');try{const result=await recognizeStudentRecordImage(file,{sourceHint:scanTarget,studentHint:selectedStudent,onProgress:({status,progress})=>{setScanProgress(Math.max(0,Math.min(1,Number(progress||0))));setScanMessage(status==='recognizing text'?'Đang đọc nội dung…':status==='preprocess'?'Đang tăng độ nét ảnh…':status==='loading tesseract core'?'Đang tải bộ OCR…':'Đang nhận diện theo bố cục…');}});setScanResult(result);setScanFields(result.fields||{});const count=Object.keys(result.fields||{}).length;setScanMessage(count?'Đã nhận diện '+count+'/'+Object.keys(STUDENT_RECORD_FIELD_LABELS).length+' mục'+(result.layoutUsed?' bằng OCR theo bố cục.':'.'):'OCR đã đọc ảnh nhưng chưa tách được trường dữ liệu. Có thể sửa thủ công bên dưới.');}catch(error){setScanMessage(error?.message||'Không thể nhận diện ảnh.');}finally{setScanBusy(false);}};
  const resolvedTarget=()=>scanTarget!=='auto'?scanTarget:scanResult?.sourceType==='vnedu'?'vnedu':scanResult?.sourceType==='moet'?'moet':'paper';
  const saveScan=async()=>{if(!selectedStudent||!selectedRecord||!scanFile)return;const target=resolvedTarget();const captureId=uid('capture');const mediaKey=await saveStudentRecordMedia({workspaceId:workspace.id,studentId:selectedStudent.id,captureId,file:scanFile});let cloud={ok:false,offline:true,message:'Cloud chưa sẵn sàng.'};if(studentRecordCloudEnabled()){try{cloud=await uploadStudentRecordCloudMedia({workspaceId:workspace.id,studentId:selectedStudent.id,captureId,file:scanFile});}catch(error){cloud={ok:false,message:error?.message||'Không thể đồng bộ cloud.'};}}const capture={id:captureId,mediaKey,cloudPath:cloud.ok?cloud.path:'',syncState:cloud.ok?'cloud':'local',name:scanFile.name||'Ảnh hồ sơ',type:scanFile.type,size:scanFile.size,cloudSize:cloud.ok?cloud.size:0,sourceType:scanResult?.sourceType||'unknown',engine:scanResult?.engine||'',confidence:scanResult?.confidence||0,createdAt:nowIso()};const nextSources={...selectedRecord.sources,[target]:{...selectedRecord.sources[target],fields:{...selectedRecord.sources[target].fields,...scanFields},captures:[...selectedRecord.sources[target].captures,capture],updatedAt:nowIso()}};let checklist={...selectedRecord.checklist};if(target==='paper'){const map={birth_certificate:'birthCertificate',transcript:'transcript',grade10_admission:'grade10Admission',completion_certificate:'completionCertificate'};const docKey=map[scanResult?.sourceType];if(docKey)checklist[docKey]='review';}await patchRecord({sources:nextSources,checklist},cloud.ok?'Đã quét và đồng bộ ảnh vào kho riêng tư.':'Đã lưu ảnh trên thiết bị; cloud sẽ đồng bộ lại khi sẵn sàng.');setScanOpen(false);setSection(target==='paper'?'paper':target);};
  const removeCapture=async(sourceKey,capture)=>{if(!window.confirm('Xóa ảnh hồ sơ này khỏi thiết bị và kho riêng tư?'))return;if(capture.cloudPath){const cloudDelete=await deleteStudentRecordCloudMedia(capture.cloudPath);if(!cloudDelete.ok){alert(cloudDelete.message||'Không thể xóa ảnh trên cloud.');return;}}await deleteStudentRecordMedia(capture.mediaKey).catch(()=>{});const source=selectedRecord.sources[sourceKey];await patchRecord({sources:{...selectedRecord.sources,[sourceKey]:{...source,captures:source.captures.filter((item)=>item.id!==capture.id)}}},'Đã xóa ảnh hồ sơ.');if(preview?.capture?.id===capture.id)setPreview(null);};
  const openCapture=async(sourceKey,capture)=>{let stored=await getStudentRecordMedia(capture.mediaKey);let blob=stored?.blob||null;if(!blob&&capture.cloudPath){const cloud=await downloadStudentRecordCloudMedia(capture.cloudPath);if(cloud.ok&&cloud.blob){blob=cloud.blob;try{const cachedFile=new File([blob],capture.name||'scan.jpg',{type:blob.type||capture.type||'image/jpeg'});await saveStudentRecordMedia({workspaceId:workspace.id,studentId:selectedStudent.id,captureId:capture.id,file:cachedFile});}catch{}}else{alert(cloud.message||'Không thể tải ảnh riêng tư.');return;}}if(!blob){alert('Ảnh chưa được đồng bộ và không còn trên thiết bị này.');return;}const url=URL.createObjectURL(blob);setPreview({sourceKey,capture,url});};
  const closePreview=()=>{if(preview?.url)URL.revokeObjectURL(preview.url);setPreview(null);};
  const syncPendingCaptures=async()=>{if(!selectedStudent||!selectedRecord||syncBusy)return;if(!studentRecordCloudEnabled()){alert('Cloud chưa được cấu hình trên thiết bị này.');return;}setSyncBusy(true);let synced=0,missing=0;try{const nextSources={...selectedRecord.sources};for(const sourceKey of ['paper','vnedu','moet']){const source=selectedRecord.sources[sourceKey];const nextCaptures=[];for(const capture of source.captures||[]){if(capture.cloudPath){nextCaptures.push(capture);continue;}const stored=await getStudentRecordMedia(capture.mediaKey);if(!stored?.blob){missing+=1;nextCaptures.push(capture);continue;}const file=new File([stored.blob],capture.name||'scan.jpg',{type:stored.type||capture.type||stored.blob.type||'image/jpeg'});const cloud=await uploadStudentRecordCloudMedia({workspaceId:workspace.id,studentId:selectedStudent.id,captureId:capture.id,file});if(cloud.ok){synced+=1;nextCaptures.push({...capture,cloudPath:cloud.path,cloudSize:cloud.size,syncState:'cloud'});}else nextCaptures.push(capture);}nextSources[sourceKey]={...source,captures:nextCaptures};}if(synced)await patchRecord({sources:nextSources},'Đã đồng bộ '+synced+' ảnh vào kho riêng tư.');else if(!missing)alert('Tất cả ảnh của học sinh này đã được đồng bộ.');if(missing)alert('Có '+missing+' ảnh chỉ tồn tại trên thiết bị cũ nên chưa thể đồng bộ.');}finally{setSyncBusy(false);}};
  const openVneduExcelPicker=()=>{if(excelBusy||excelImporting)return;setExcelError('');excelFileRef.current?.click();};
